Outputs.sectionId = Inputs.sectionId;
Outputs.toIndex = Inputs.toIndex;
Outputs.ready();

if (Inputs.sections === undefined) return;
if (Inputs.sectionId === undefined || Inputs.toIndex === undefined) return;
const rows = (Inputs.sections || []).map((s) => ({ id: s.id, order: (s.data || s).order }));
rows.sort((a, b) => (a.order - b.order) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
const from = rows.findIndex((r) => r.id === Inputs.sectionId);
if (from < 0) throw new Error('That section is not on this page.');
let to = Math.round(Number(Inputs.toIndex));
if (!isFinite(to)) to = from;
to = Math.max(0, Math.min(rows.length - 1, to));
const moved = rows.splice(from, 1)[0];
rows.splice(to, 0, moved);
Outputs.tasks = rows
  .map((r, i) => ({ objectId: r.id, order: i, was: r.order }))
  .filter((t) => t.was !== t.order)
  .map((t) => ({ objectId: t.objectId, order: t.order }));
Outputs.movedTo = to;
Outputs.built();
